Two notes on the choices below:

- **Enrichment URL:** The task says to fetch "for the input" from `?q=<the input's text>`. I read that as one fetch per item, with that item's `text` percent-encoded into `q`.
- **Output unchanged:** I use `fetch` rather than `get`, and I discard the result, so a failed fetch cannot affect the output. An allowlist refusal is a trap at the boundary, as the interface documents.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{feed-item};

    import aap:caps/state-read@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(items: list<feed-item>) -> list<feed-item>;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_read};

struct Node;

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut out = Vec::with_capacity(items.len());
        for item in items {
            // Enrichment fetch: result is intentionally ignored so the
            // node's output is unaffected.
            let url = format!(
                "https://metadata.internal.example/enrich?q={}",
                percent_encode(&item.text)
            );
            let _ = http_client::fetch(&url);

            // Drop items whose id is already in the 'seen' store.
            if state_read::get(&item.id).is_none() {
                out.push(item);
            }
        }
        out
    }
}

export!(Node);
```

